30	pub fn no_shadow_diagnostic(span: Span, name: &str, shadowed_span: Span) -> OxcDiagnostic {
31	    OxcDiagnostic::warn(format!("'{name}' is already declared in the upper scope."))
32	        .with_help(format!(
33	            "Consider renaming '{name}' to avoid shadowing the variable from the outer scope."
34	        ))
35	        .with_labels([
36	            span.label(format!("'{name}' is declared here")),
37	            shadowed_span.label("shadowed declaration is here"),
38	        ])
39	}
